CID=$(docker ps --filter "name=supabase_db_sellery" -q)
docker exec -i "$CID" psql -U postgres -d postgres -v ON_ERROR_STOP=1 <<'SQL' 2>&1 | tail -45
\pset pager off
begin;
select id as cid, code, status, start_date, end_date, sold_qty
  from public.campaigns where status='LIVE' order by code limit 1 \gset
\echo '--- 대상 캠페인:' :'code' :'status' '기간' :'start_date' '~' :'end_date'

\echo ''
\echo '--- 1) 사유 없이 중단 → BAD_REASON 이어야 한다'
select public.app_admin_end_sale(:'cid', '   ', null) as r;

\echo '--- 2) 중단 전 campaign_card 구매 게이트(status)'
select public.campaign_card(:'code') -> 'campaign' ->> 'status' as card_status;

\echo '--- 3) 사유 넣고 중단 → ok · CLEARING · due_on'
select public.app_admin_end_sale(:'cid', '  표시광고   문의 접수 — 성분 표기 확인  ', null) as r;

\echo '--- 4) 중단 뒤 상태 · end_date 가 유지됐는지(설계 결정 2)'
select status, start_date, end_date from public.campaigns where id = :'cid';

\echo '--- 5) 고객 카드도 CLEARING (구매 게이트는 LIVE 만 통과)'
select public.campaign_card(:'code') -> 'campaign' ->> 'status' as card_status;

\echo '--- 6) 이벤트 (사유 공백 정규화 확인)'
select event_type, actor_role, body, payload->>'reason' as reason, payload->>'due_on' as due_on
  from public.campaign_events where campaign_id = :'cid' order by created_at desc limit 1;

\echo '--- 7) 다시 중단 → already'
select public.app_admin_end_sale(:'cid', '중복', null) as r;

\echo '--- 8) 재개 → ok · LIVE'
select public.app_admin_resume_sale(:'cid', null) as r;

\echo '--- 9) 다시 재개 → already'
select public.app_admin_resume_sale(:'cid', null) as r;
rollback;
SQL

