input.command:
CID=$(docker ps --filter "name=supabase_db_sellery" -q)
docker exec -i "$CID" psql -U postgres -d postgres -At <<'SQL' 2>&1
begin;
select o.id as oid, o.code as ocode, o.campaign_id as cid, o.customer_id as ocust
  from public.orders o join public.campaigns c on c.id=o.campaign_id
 where c.status in ('LIVE','CLEARING','SETTLED') and o.status='PAID' and o.customer_id is not null
 order by o.code limit 1 \gset
\echo '대상:' :'ocode'

\echo '=== C) 정상: 같은 고객 행(customer_id) → true 기대 ==='
select public.app_cs_open(:'cid', :'ocust', null, '고객', '배송 문의', '본문', :'ocode', null) -> 'order_matched';

\echo '=== C2) 다른 고객 행으로 사칭 → false 기대 ==='
select id as foreign_cust from public.customers where id <> :'ocust' limit 1 \gset
select public.app_cs_open(:'cid', :'foreign_cust', null, '공격자', '배송 문의', '본문', :'ocode', null) -> 'order_matched';

\echo '=== D) 정상: 비회원 조회 토큰 → true 기대 ==='
update public.customers set guest = true where id = :'ocust';
select public.guest_token_rotate(:'ocust') as tok \gset
select public.app_cs_open(:'cid', null, null, '비회원', '배송 문의', '본문', :'ocode', :'tok') -> 'order_matched';

\echo '=== E) 차단: 맞는 토큰 + 다른 캠페인 → false 기대 ==='
select id as other_cid from public.campaigns
 where status in ('LIVE','CLEARING','SETTLED') and id <> :'cid' order by code limit 1 \gset
select public.app_cs_open(:'other_cid', null, null, '공격자', '배송 문의', '본문', :'ocode', :'tok') -> 'order_matched';

\echo '=== F) 미매칭에도 주문번호 원문 보관 ==='
select order_code, (order_id is null) as id_null from public.cs_conversations
 where buyer_name='공격자' order by created_at desc limit 1;

\echo '=== G) 주문번호 없는 평범한 접수는 그대로 동작 ==='
select public.app_cs_open(:'cid', null, null, '고객', '상품 문의', '성분 문의드려요', null, null) -> 'ok';
rollback;
SQL

