  from public.orders o join public.campaigns c on c.id=o.campaign_id
 where c.status in ('LIVE','CLEARING','SETTLED') and o.status='PAID' order by o.code limit 1 \gset

-- 픽스처: 이 주문의 주인을 비회원 고객 행으로 만든다 (0021 비회원 구매와 같은 모양)
insert into public.customers (guest, name, phone) values (true, '테스트고객', '010-0000-0000') returning id as ocust \gset
insert into public.customers (guest, name, phone) values (true, '남', '010-1111-1111') returning id as foreign_cust \gset
update public.orders set customer_id = :'ocust' where id = :'oid';
select public.guest_token_rotate(:'ocust') as tok \gset

\echo 'A) 소유 증명 없음 → false 기대:'
select public.app_cs_open(:'cid', null, null, '공격자', '배송 문의', '본문', :'ocode', null) -> 'order_matched';
\echo 'B) 엉터리 토큰 → false 기대:'
select public.app_cs_open(:'cid', null, null, '공격자', '배송 문의', '본문', :'ocode', repeat('a',64)) -> 'order_matched';
\echo 'C) 같은 고객 행 → true 기대:'
select public.app_cs_open(:'cid', :'ocust', null, '고객', '배송 문의', '본문', :'ocode', null) -> 'order_matched';
\echo 'C2) 남의 고객 행으로 사칭 → false 기대:'
select public.app_cs_open(:'cid', :'foreign_cust', null, '공격자', '배송 문의', '본문', :'ocode', null) -> 'order_matched';
\echo 'D) 비회원 조회 토큰 → true 기대:'
select public.app_cs_open(:'cid', null, null, '비회원', '배송 문의', '본문', :'ocode', :'tok') -> 'order_matched';

select id as other_cid from public.campaigns
 where status in ('LIVE','CLEARING','SETTLED') and id <> :'cid' order by code limit 1 \gset
\echo 'E) 맞는 토큰 + 다른 캠페인 → false 기대:'
select public.app_cs_open(:'other_cid', null, null, '공격자', '배송 문의', '본문', :'ocode', :'tok') -> 'order_matched';

\echo 'F) 미매칭에도 주문번호 원문 보관 (order_code, order_id is null):'
select order_code, (order_id is null) from public.cs_conversations where buyer_name='공격자' order by created_at desc limit 1;
\echo 'G) 주문번호 없는 평범한 접수 → ok:'
select public.app_cs_open(:'cid', null, null, '고객', '상품 문의', '성분 문의드려요', null, null) -> 'ok';
\echo 'H) 기존 가드 유지 (BAD_TYPE / BAD_BODY):'
select public.app_cs_open(:'cid', null, null, '고객', '없는유형', '본문', null, null) -> 'code';
select public.app_cs_open(:'cid', null, null, '고객', '기타', '  ', null, null) -> 'code';
rollback;
SQL

