export const FAIL_SESSION_DEFAULT_CODE = "USER_CANCELED";

/**
 * `/checkout/fail` 이 `checkout_sessions.fail_code` 에 적을 값.
 * 토스가 준 code 는 형식(`^[A-Z_]{1,40}$`)이 맞을 때만 쓴다 — 공개 URL 파라미터라 그대로 저장하지 않는다.
