/** 본인의 미만료 PENDING 세션 qty 합(이 캠페인) — 곧 SUPERSEDED 될 예약분이라 소프트 재고에서 되돌린다 */
async function ownPendingQty(admin: Admin, userId: string, campaignId: string): Promise<number> {
	const { data, error } = await admin
		.from('checkout_sessions')
		.select('qty')
		.eq('user_id', userId)
		.eq('campaign_id', campaignId)
		.eq('status', 'PENDING')
		.gt('expires_at', new Date().toISOString());
	if (error) {
		console.error('[checkout] own pending read failed:', error.message);
		return 0;
	}
	return (data ?? []).reduce((sum, r) => sum + (r.qty ?? 0), 0);
}

/**
 * 비회원 판(0042) — 아는 세션이 쿠키가 가리키는 **한 건**뿐이라 그 세션만 본다.
 * `slry_gck` 는 서버가 세션 생성 때 심는 HttpOnly 쿠키라 소유 증명으로 쓸 수 있다.
 */
async function guestPendingQty(admin: Admin, sessionId: string, campaignId: string): Promise<number> {
	const { data, error } = await admin
		.from('checkout_sessions')
		.select('qty')
		.eq('id', sessionId)
		.is('user_id', null)
		.eq('campaign_id', campaignId)
		.eq('status', 'PENDING')
		.gt('expires_at', new Date().toISOString())
		.maybeSingle();
	if (error) {
		console.error('[checkout] guest pending read failed:', error.message);
		return 0;
	}
	return data?.qty ?? 0;
}

