CID=$(docker ps --filter "name=supabase_db_sellery" -q)
docker exec -i "$CID" psql -U postgres -d postgres -At <<'SQL' 2>&1
begin;
select id as cid, code as ccode from public.campaigns where status='SCHEDULE_CONFIRMED' order by code limit 1 \gset
select id as liveid from public.campaigns where status='LIVE' order by code limit 1 \gset
select id as u1 from auth.users where email is not null and btrim(email) <> '' order by created_at limit 1 \gset
\echo '대상 캠페인(SCHEDULE_CONFIRMED):' :'ccode'

\echo '1) 신청 → ok, already=false'
select public.app_campaign_alert_subscribe(:'cid', :'u1');
\echo '2) 같은 신청 → already=true'
select public.app_campaign_alert_subscribe(:'cid', :'u1') -> 'already';
\echo '3) 상태 → subscribed/can_subscribe/has_email'
select public.app_campaign_alert_state(:'cid', :'u1');
\echo '4) 비로그인(null) 상태 → 전부 false'
select public.app_campaign_alert_state(:'cid', null);
\echo '5) LIVE 캠페인에 신청 → WRONG_STATUS'
select public.app_campaign_alert_subscribe(:'liveid', :'u1') -> 'code';
\echo '6) 취소 → ok · 상태 subscribed=false'
select public.app_campaign_alert_cancel(:'cid', :'u1') -> 'already';
select public.app_campaign_alert_state(:'cid', :'u1') -> 'subscribed';
\echo '7) 재신청 → 되살아난다(already=false)'
select public.app_campaign_alert_subscribe(:'cid', :'u1') -> 'already';
select public.app_campaign_alert_state(:'cid', :'u1') -> 'subscribed';
\echo '8) 행이 1개인가(유니크)'
select count(*) from public.campaign_alerts where campaign_id = :'cid' and user_id = :'u1';
rollback;
SQL

