begin;
select id as cid, code as ccode from public.campaigns where status='SCHEDULE_CONFIRMED' order by code limit 1 \gset
select id as u1 from auth.users where email is not null and btrim(email) <> '' order by created_at limit 1 \gset
select public.app_campaign_alert_subscribe(:'cid', :'u1') -> 'ok' \gset r1_
\echo '신청 완료. 지금은 SCHEDULE_CONFIRMED 라 발송 대상 0 이어야:'
select jsonb_array_length(public.app_campaign_alerts_due(200) -> 'rows');

\echo '--- 틱으로 LIVE 전이 (start_date 를 오늘로) ---'
update public.campaigns set start_date = current_date where id = :'cid';
select public.app_campaign_tick_one(:'cid') -> 'went_live';
\echo '발송 대상 1건이어야:'
select jsonb_array_length(public.app_campaign_alerts_due(200) -> 'rows');
\echo '행 내용(이메일·토큰·상품명 포함):'
select jsonb_pretty(public.app_campaign_alerts_due(200) -> 'rows' -> 0);

select (public.app_campaign_alerts_due(200) -> 'rows' -> 0 ->> 'alert_id') as aid \gset
select (public.app_campaign_alerts_due(200) -> 'rows' -> 0 ->> 'unsub_token') as tok \gset

\echo '--- 발송 완료 기록 → marked=1, 재호출 marked=0 (멱등) ---'
select public.app_campaign_alert_sent(array[:'aid']::uuid[]) -> 'marked';
select public.app_campaign_alert_sent(array[:'aid']::uuid[]) -> 'marked';
\echo '발송 후 대상 0 이어야:'
select jsonb_array_length(public.app_campaign_alerts_due(200) -> 'rows');

\echo '--- 1클릭 수신거부(토큰) → ok, 재호출 already ---'
select public.app_campaign_alert_unsubscribe(:'tok'::uuid) -> 'already';
select public.app_campaign_alert_unsubscribe(:'tok'::uuid) -> 'already';
\echo '없는 토큰 → NOT_FOUND:'
select public.app_campaign_alert_unsubscribe('00000000-0000-4000-8000-000000000000'::uuid) -> 'code';
rollback;
SQL

