input.command:
CID=$(docker ps --filter "name=supabase_db_sellery" -q)
docker exec -i "$CID" psql -U postgres -d postgres -v ON_ERROR_STOP=1 < supabase/migrations/0046_fast_review_repeat.sql 2>&1 | tail -3
docker exec -i "$CID" psql -U postgres -d postgres -At <<'SQL' 2>&1
begin;
select id as b1 from public.brands order by code limit 1 \gset
insert into public.celery_ledger (owner_type, brand_id, delta, reason, memo) values ('brand', :'b1', 10, 'admin_grant', 'test');
update public.products set status='pending' where brand_id = :'b1' and deleted_at is null and code in (select code from public.products where brand_id = :'b1' order by code limit 2);
\echo '--- 1회차 ---'
select public.app_shop_buy('brand', :'b1', 'fastreview') -> 'applied';
\echo '--- 상품 1건 다시 대기로 → 2회차 (이제 통과해야) ---'
update public.products set status='pending' where brand_id = :'b1' and code = (select code from public.products where brand_id = :'b1' order by code limit 1);
select public.app_shop_buy('brand', :'b1', 'fastreview') -> 'applied';
\echo '--- 샵 카탈로그: fastreview 가 보유 중이 아닌가 ---'
select public.app_shop_catalog('brand', :'b1') -> 'items';
rollback;
SQL

