  from campaigns c join sellers s on s.id=c.seller_id join brands b on b.id=c.brand_id
 where c.status='LIVE' order by c.code limit 1 \gset
\echo '대상: 캠페인' :'ccode' '· 셀러' :'scode' '· 브랜드' :'bcode'
\echo ''
\echo '정지 전 고객 카드:'
select case when public.campaign_card(:'ccode') is null then '404 (카드 없음)' else 'LIVE 정상' end;

\echo '--- 셀러 정지 ---'
update sellers set active=false where id=:'sid';
select case when public.campaign_card(:'ccode') is null then '404 (카드 없음) ← 판매 링크 죽음' else '정상' end;
\echo '그 셀러의 LIVE 캠페인 수:'
select count(*) from campaigns where seller_id=:'sid' and status='LIVE';
update sellers set active=true where id=:'sid';

\echo '--- 브랜드 정지 ---'
update brands set active=false where id=:'bid';
select case when public.campaign_card(:'ccode') is null then '404 (카드 없음) ← 판매 링크 죽음' else '정상' end;
\echo '그 브랜드의 LIVE 캠페인 수:'
select count(*) from campaigns c join products p on p.id=c.product_id where p.brand_id=:'bid' and c.status='LIVE';
rollback;
SQL

