begin;
select id as cid, code from campaigns where status='CLEARING' order by code limit 1 \gset
\echo '대상:' :'code'
create temp table before_ as
 select 'settlements' t, count(*) n from settlements
 union all select 'payouts', count(*) from payouts
 union all select 'referral_earnings', count(*) from referral_earnings
 union all select 'campaign_events', count(*) from campaign_events;
select public.app_admin_settle_run(:'cid', null, true) -> 'ok' as ok;
\echo '정산 후 늘어난 행:'
select b.t||': +'||(a.n - b.n)
  from before_ b join (
    select 'settlements' t, count(*) n from settlements
    union all select 'payouts', count(*) from payouts
    union all select 'referral_earnings', count(*) from referral_earnings
    union all select 'campaign_events', count(*) from campaign_events) a on a.t=b.t
 where a.n <> b.n;
\echo '캠페인 상태:'
select status from campaigns where id=:'cid';
\echo '되돌리려면 손대야 할 것 = 위 테이블 + campaigns.status + 지급 상태';
rollback;
SQL

