python3 - <<'EOF'
p='apps/admin/src/routes/(console)/(money)/settle/[code]/+page.server.ts'
s=open(p,encoding='utf-8').read()
old = """	run: async (event) => {
		const { gate, str } = await enter(event, 'run');
		const force = str('force') === '1';
		const res = await runSettlement(event.params.code, { actorUserId: gate.ctx.user.id, force });
		if (!res.ok) return fail(400, { kind: 'run' as const, ok: false as const, message: settleRunSummary(res) });
		return { kind: 'run' as const, ok: true as const, message: settleRunSummary(res), already: res.already };
	},"""
new = """	run: async (event) => {
		const { gate, str } = await enter(event, 'run');
		const force = str('force') === '1';
		// 기일 전 강제 실행은 **사유 필수**(0047) — 지금은 memo 에 남아 "누가 왜 당겼는지" 를 추적할 수 있다.
		// 빈 값은 RPC 까지 가지 않고 폼 오류로 돌려준다(입력값을 잃지 않게).
		const forceReason = str('force_reason').slice(0, 200);
		if (force && !forceReason.trim()) {
			return fail(400, {
				kind: 'run' as const,
				ok: false as const,
				message: '기준일 전에 실행하려면 사유를 적어주세요 — 정산 명세에 남습니다.'
			});
		}
		const res = await runSettlement(event.params.code, { actorUserId: gate.ctx.user.id, force, forceReason: force ? forceReason : null });
		if (!res.ok) return fail(400, { kind: 'run' as const, ok: false as const, message: settleRunSummary(res) });
		return { kind: 'run' as const, ok: true as const, message: settleRunSummary(res), already: res.already };
	},

	/**
	 * 미지급 정산 취소 (0047) — `payouts` 가 전부 `pending` 일 때만. 하나라도 지급 완료면 RPC 가
	 * `HAS_PAID` 로 막는다(이중 지급 방지). 이미 보낸 뒤의 정정은 만들지 않았다.
	 */
	cancelSettle: async (event) => {
		const { gate, self, str } = await enter(event, 'cancel-settle');
		const reason = str('reason').slice(0, 200);
		if (!reason.trim()) redirect(303, `${self}?err=${encodeURIComponent('취소 사유를 적어주세요 — 캠페인 스레드에 남습니다.')}`);
		const res = await cancelSettlement(event.params.code, reason, gate.ctx.user.id);
		if (!res.ok) {
			const msg =
				res.code === 'HAS_PAID'
					? `이미 지급이 완료된 건이 ${res.paidCount ?? 1}개 있어 취소할 수 없습니다 — 나간 돈은 되돌릴 수 없습니다.`
					: res.code === 'WRONG_STATUS'
						? '정산된 캠페인이 아닙니다.'
						: res.code === 'NO_SETTLEMENT'
							? '정산 스냅샷이 없습니다 — 운영팀에 확인해주세요.'
							: adminSettleFailMessage(res.code);
			redirect(303, `${self}?err=${encodeURIComponent(msg)}`);
		}
		redirect(303, `${self}?msg=settle_canceled`);
	},"""
assert old in s
s=s.replace(old,new,1)
open(p,'w',encoding='utf-8').write(s)
print("OK")
EOF
